from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if k < -total or k > total:
            return -1

        offset = total
        idx = k + offset

        # DP for positive products (subsequences containing no zero)
        dp = [[0, 0] for _ in range(limit + 1)]
        dp[1][0] = 1 << offset  # empty subsequence: product 1, sum 0, parity 0

        for x in nums:
            if x == 0:
                continue

            new_dp = [row[:] for row in dp]  # skip x
            max_p = limit // x
            for p in range(1, max_p + 1):
                b0 = dp[p][0]
                if b0:
                    new_dp[p * x][1] |= b0 << x
                b1 = dp[p][1]
                if b1:
                    new_dp[p * x][0] |= b1 >> x
            dp = new_dp

        count_ones = nums.count(1)

        for p in range(limit, 0, -1):
            b = dp[p][0] | dp[p][1]
            if (b >> idx) & 1:
                if p == 1 and k == 0:
                    # The empty subsequence also has product 1 and sum 0.
                    # We need at least two ones to form a non-empty product-1 sum-0 subsequence.
                    if count_ones >= 2:
                        return 1
                    continue
                return p

        # DP for subsequences containing at least one zero -> product is always 0
        if 0 in nums:
            dpz = [[0, 0] for _ in range(2)]  # dpz[has_zero][parity]
            dpz[0][0] = 1 << offset

            for x in nums:
                new = [row[:] for row in dpz]  # skip x
                for hz in (0, 1):
                    for par in (0, 1):
                        bits = dpz[hz][par]
                        if bits:
                            nhz = 1 if (hz or x == 0) else 0
                            npar = par ^ 1
                            if par == 0:
                                shifted = bits << x
                            else:
                                shifted = bits >> x
                            new[nhz][npar] |= shifted
                dpz = new

            if ((dpz[1][0] | dpz[1][1]) >> idx) & 1:
                return 0

        return -1

import sys

def solve():
    input = sys.stdin.readline
    T = int(input().strip())

    # Precompute combine table for Minkowski sum (xor) of parity masks.
    # Each mask is an 8-bit integer representing a set of states 0..7.
    combine = [[0] * 256 for _ in range(256)]
    for a in range(256):
        for b in range(256):
            res = 0
            for i in range(8):
                if (a >> i) & 1:
                    for j in range(8):
                        if (b >> j) & 1:
                            res |= 1 << (i ^ j)
            combine[a][b] = res

    out_lines = []
    for _ in range(T):
        line = input().strip()
        while line == '':
            line = input().strip()
        N, K = map(int, line.split())
        items = []
        for _ in range(N):
            X, Y, Z = map(int, input().split())
            M = X if X >= Y else Y
            if Z > M:
                M = Z
            mask = 0
            if X == M: mask |= 1 << 0
            if Y == M: mask |= 1 << 1
            if Z == M: mask |= 1 << 2
            items.append((M, X, Y, Z, mask))

        # Sort by M descending
        items.sort(key=lambda x: x[0], reverse=True)

        S_items = items[:2 * K]
        U_items = items[2 * K:]
        Base = sum(item[0] for item in S_items)
        n = len(S_items)

        if n == 0:
            out_lines.append("0")
            continue

        # Build segment tree for S_items
        size = 1
        while size < n:
            size *= 2
        tree = [1] * (2 * size)
        for i in range(n):
            tree[size + i] = S_items[i][4]  # argmax mask
        for i in range(n, size):
            tree[size + i] = 1
        for i in range(size - 1, 0, -1):
            tree[i] = combine[tree[2 * i]][tree[2 * i + 1]]

        def query(l, r):
            if l > r:
                return 1
            l += size
            r += size
            res_left = 1
            res_right = 1
            while l <= r:
                if l & 1:
                    res_left = combine[res_left][tree[l]]
                    l += 1
                if not (r & 1):
                    res_right = combine[tree[r]][res_right]
                    r -= 1
                l >>= 1
                r >>= 1
            return combine[res_left][res_right]

        ACH_all = query(0, n - 1)
        if ACH_all & 1:  # 0 is achievable
            out_lines.append(str(Base))
            continue

        # Generate candidate operations
        sources = [[] for _ in range(3)]   # (M, idx) top 2 smallest M per source color
        targets = [[] for _ in range(3)]   # (v, idx) top 2 largest v per target color
        best_recolor = {}                  # (p,q) -> list of (cost, idx) top 2

        for idx, item in enumerate(S_items):
            M, X, Y, Z, mask = item
            v = (X, Y, Z)
            for p in range(3):
                if mask & (1 << p):
                    lst = sources[p]
                    lst.append((M, idx))
                    lst.sort()
                    if len(lst) > 2:
                        lst.pop()
                    for q in range(3):
                        if q == p:
                            continue
                        cost = M - v[q]
                        key = (p, q)
                        if key not in best_recolor:
                            best_recolor[key] = [(cost, idx)]
                        else:
                            lst2 = best_recolor[key]
                            lst2.append((cost, idx))
                            lst2.sort()
                            if len(lst2) > 2:
                                lst2.pop()

        for j, item in enumerate(U_items):
            M, X, Y, Z, mask = item
            v = (X, Y, Z)
            for q in range(3):
                lst = targets[q]
                lst.append((v[q], j))
                lst.sort(reverse=True)
                if len(lst) > 2:
                    lst.pop()

        ops = []
        for p in range(3):
            for q in range(3):
                if p == q:
                    continue
                # Recolor operations
                key = (p, q)
                if key in best_recolor:
                    for cost, idx in best_recolor[key]:
                        ops.append(('R', p, q, idx, -1, cost))
                # Swap operations
                for Mi, i in sources[p]:
                    for Vj, j in targets[q]:
                        cost = Mi - Vj
                        ops.append(('S', p, q, i, j, cost))

        INF = 10**18
        best_loss = INF

        def get_mask_excluding(indices):
            if not indices:
                return ACH_all
            idxs = sorted(indices)
            res = 1
            prev = 0
            for idx in idxs:
                if prev <= idx - 1:
                    res = combine[res][query(prev, idx - 1)]
                prev = idx + 1
            if prev <= n - 1:
                res = combine[res][query(prev, n - 1)]
            return res

        # Single operation
        for op in ops:
            typ, p, q, src, tgt, cost = op
            T = 1 << q
            mask_rem = get_mask_excluding([src])
            if (mask_rem >> T) & 1:
                if cost < best_loss:
                    best_loss = cost

        # Two operations
        m = len(ops)
        for i in range(m):
            typ1, p1, q1, src1, tgt1, cost1 = ops[i]
            for j in range(i + 1, m):
                typ2, p2, q2, src2, tgt2, cost2 = ops[j]
                if src1 == src2:
                    continue
                if typ1 == 'S' and typ2 == 'S' and tgt1 == tgt2:
                    continue
                T = (1 << q1) ^ (1 << q2)
                mask_rem = get_mask_excluding([src1, src2])
                if (mask_rem >> T) & 1:
                    total_cost = cost1 + cost2
                    if total_cost < best_loss:
                        best_loss = total_cost

        ans = Base - best_loss
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1]
    T = data[2]

    # Build the mapping from characters in S to characters in T.
    mp = {}
    for i in range(N):
        c = S[i]
        d = T[i]
        if c in mp:
            if mp[c] != d:
                print(-1)
                return
        else:
            mp[c] = d

    P = set(mp.keys())

    # Special impossible case:
    # If all 26 letters appear in both S and T, and S != T,
    # then the mapping is a non-identity permutation and no free letter exists.
    if len(P) == 26 and len(set(T)) == 26 and S != T:
        print(-1)
        return

    # E = number of characters that need to change at least once.
    E = 0
    indeg = [0] * 26
    for c in P:
        d = mp[c]
        if d != c:
            E += 1
        indeg[ord(d) - 97] += 1

    # Find all non-trivial cycles in the functional graph on P.
    # A cycle needs an extra operation iff every node in it has indegree exactly 1.
    state = [0] * 26  # 0: unvisited, 1: visiting, 2: done
    extra = 0

    for c in P:
        idx = ord(c) - 97
        if state[idx] == 0:
            path = []
            u = c
            while u in P and state[ord(u) - 97] == 0:
                state[ord(u) - 97] = 1
                path.append(u)
                u = mp[u]

            if u in P and state[ord(u) - 97] == 1:
                start = path.index(u)
                cycle = path[start:]
                if len(cycle) >= 2:
                    if all(indeg[ord(v) - 97] == 1 for v in cycle):
                        extra += 1

            for v in path:
                state[ord(v) - 97] = 2

    print(E + extra)


