import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    # Binomial coefficients up to K
    C = [[0] * (K + 1) for _ in range(K + 1)]
    for n in range(K + 1):
        C[n][0] = C[n][n] = 1
        for r in range(1, n):
            C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

    # P[p] = sum of S_i^p over already processed prefix sums S_i
    P = [0] * (K + 1)
    P[0] = 1  # S_0 = 0

    pref = 0
    ans = 0

    for a in A:
        pref = (pref + a) % MOD

        pw = [1] * (K + 1)
        for p in range(1, K + 1):
            pw[p] = pw[p - 1] * pref % MOD

        for t in range(K + 1):
            term = C[K][t] * pw[t] % MOD * P[K - t] % MOD
            if (K - t) & 1:
                ans -= term
            else:
                ans += term

        ans %= MOD

        P[0] += 1
        if P[0] >= MOD:
            P[0] -= MOD

        for p in range(1, K + 1):
            P[p] += pw[p]
            if P[p] >= MOD:
                P[p] -= MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

import sys
import bisect

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N = data[0]
    A = data[1:1 + N]
    B = data[1 + N:1 + 2 * N]

    ca = {}
    for x in A:
        if x != -1:
            ca[x] = ca.get(x, 0) + 1
    cb = {}
    for x in B:
        if x != -1:
            cb[x] = cb.get(x, 0) + 1

    fa = sum(ca.values())
    fb = sum(cb.values())

    # Minimum number of fixed A - fixed B pairs required
    req = fa + fb - N
    if req <= 0:
        print("Yes")
        return

    maxA = max(ca) if ca else 0
    maxB = max(cb) if cb else 0
    L = max(maxA, maxB, 0)

    ca_items = sorted(ca.items())
    cb_items = sorted(cb.items())
    cb_vals = [b for b, _ in cb_items]

    packed = []
    for a, ca_count in ca_items:
        # Only consider b such that a + b >= L
        start = bisect.bisect_left(cb_vals, L - a)
        for idx in range(start, len(cb_items)):
            b, cb_count = cb_items[idx]
            s = a + b
            contrib = ca_count if ca_count < cb_count else cb_count
            # Pack sum and contribution into one integer
            packed.append((s << 11) | contrib)

    if not packed:
        print("No")
        return

    packed.sort()

    prev_s = -1
    accum = 0
    for p in packed:
        s = p >> 11
        contrib = p & 2047
        if s == prev_s:
            accum += contrib
        else:
            if prev_s >= L and accum >= req:
                print("Yes")
                return
            prev_s = s
            accum = contrib

    if prev_s >= L and accum >= req:
        print("Yes")
    else:
        print("No")


if __name__ == "__main__":
    solve()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    T = int(data[0])
    ptr = 1
    OFFSET = 10 ** 6
    out = []

    for _ in range(T):
        R = int(data[ptr])
        B = int(data[ptr + 1])
        ptr += 2

        # Necessary conditions
        if R % 2 == 1:
            out.append("No")
            continue
        if R == 0 and B % 2 == 1:
            out.append("No")
            continue

        out.append("Yes")

        if R == 0:
            # All blue, B is even and B >= 2
            if B == 2:
                verts = [(0, 0, 'B'), (1, 1, 'B')]
            else:
                b = B // 2 - 1
                xy = [(0, 0)]
                for i in range(1, b + 1):
                    xy.append((i, 0))
                xy.append((b, 1))
                for i in range(b - 1, -1, -1):
                    xy.append((i, 1))

                verts = []
                for x, y in xy:
                    verts.append((x + y + 1, x - y, 'B'))

            for r, c, p in verts:
                out.append(f"{p} {r + OFFSET} {c + OFFSET}")

        elif B == 0:
            # All red, R is even and R >= 2
            if R == 2:
                verts = [(0, 0, 'R'), (1, 0, 'R')]
            else:
                b = R // 2 - 1
                verts = [(0, 0, 'R')]
                for i in range(1, b + 1):
                    verts.append((0, i, 'R'))
                verts.append((1, b, 'R'))
                for i in range(b - 1, -1, -1):
                    verts.append((1, i, 'R'))

            for r, c, p in verts:
                out.append(f"{p} {r + OFFSET} {c + OFFSET}")

        else:
            # R > 0, R even, B > 0
            L = R - 1
            l = (L - 1) // 2
            verts = [(0, 0, 'R')]

            if B % 2 == 1:
                k = B // 2
                blue_path = [(1, 0)]
                for i in range(1, k + 1):
                    blue_path.append((i + 1, i))
                blue_path.append((k, k + 1))
                for t in range(1, k + 1):
                    blue_path.append((k - t, k - t + 1))

                for r, c in blue_path[:-1]:
                    verts.append((r, c, 'B'))

                C = blue_path[-1]
                red_path = [C]
                if l == 0:
                    red_path.append((0, 0))
                else:
                    for i in range(1, l + 1):
                        red_path.append((-i, 1))
                    red_path.append((-l, 0))
                    for i in range(l - 1, -1, -1):
                        red_path.append((-i, 0))

                for r, c in red_path[:-1]:
                    verts.append((r, c, 'R'))

            else:
                k = B // 2
                blue_path = [(1, 0)]
                for i in range(1, k):
                    blue_path.append((i + 1, i))
                blue_path.append((k - 1, k))
                for s in range(1, k + 1):
                    blue_path.append((k - 1 - s, k - s))

                for r, c in blue_path[:-1]:
                    verts.append((r, c, 'B'))

                C = blue_path[-1]
                red_path = [C]
                if l == 0:
                    red_path.append((0, 0))
                else:
                    a = l - 1
                    for i in range(1, a + 1):
                        red_path.append((-1 - i, 0))
                    red_path.append((-l, -1))
                    for row in range(-l + 1, 1):
                        red_path.append((row, -1))
                    red_path.append((0, 0))

                for r, c in red_path[:-1]:
                    verts.append((r, c, 'R'))

            for r, c, p in verts:
                out.append(f"{p} {r + OFFSET} {c + OFFSET}")

    sys.stdout.write("\n".join(out))


