from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def need(x: int) -> int:
            cnt = 1
            while x >= 4:
                x //= 4
                cnt += 1
            return cnt

        def prefix(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            k = 1
            low = 1
            while low <= n:
                high = low * 4 - 1
                if high > n:
                    high = n
                total += k * (high - low + 1)
                k += 1
                low *= 4
            return total

        ans = 0
        for l, r in queries:
            s = prefix(r) - prefix(l - 1)
            ops = (s + 1) // 2
            m = need(r)
            if m > ops:
                ops = m
            ans += ops
        return ans

