import sys
from collections import deque

def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    # If N is odd, final complete bipartite graph always has an even number of edges.
    # Thus total moves parity = M mod 2.
    if N % 2 == 1:
        print("Aoki" if M % 2 == 1 else "Takahashi")
        return

    visited = [False] * (N + 1)
    color = [-1] * (N + 1)

    K = 0          # number of odd-size components
    E = 0          # number of even-size components
    P_even = 0     # sum of (size of one color class mod 2) over even components
    K_int = 0      # total missing internal edges (a*b - m)

    for i in range(1, N + 1):
        if not visited[i]:
            q = deque([i])
            visited[i] = True
            color[i] = 0
            comp = []
            while q:
                u = q.popleft()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        color[v] = color[u] ^ 1
                        q.append(v)

            a = b = 0
            for u in comp:
                if color[u] == 0:
                    a += 1
                else:
                    b += 1

            size = a + b
            # count edges inside this component
            m = sum(len(adj[u]) for u in comp) // 2

            if size % 2 == 1:
                K += 1
            else:
                E += 1
                P_even += (a % 2)
            K_int += a * b - m

    T = K // 2

    if K == 0:
        # no odd components: outcome determined solely by fixed parity
        if (P_even + M) % 2 == 1:
            print("Aoki")
        else:
            print("Takahashi")
    elif T == 1:
        # exactly one odd-odd merge needed; first player can always win
        print("Aoki")
    else:
        # T >= 2
        if M == 0:
            # all vertices are isolated
            if T % 2 == 1:
                print("Aoki")
            else:
                print("Takahashi")
        else:
            P = E + K_int
            if P % 2 == 1:
                print("Aoki")
            else:
                print("Takahashi")

if __name__ == "__main__":
    solve()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))

            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, digit_prod: int, tight: bool, started: bool) -> int:
                if pos == len(digits):
                    if not started:
                        return 0
                    return 1 if digit_prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == limit)

                    if not started and d == 0:
                        total += dp(pos + 1, 0, 1, next_tight, False)
                    else:
                        if started:
                            total += dp(pos + 1, digit_sum + d, digit_prod * d, next_tight, True)
                        else:
                            total += dp(pos + 1, d, d, next_tight, True)

                return total

            return dp(0, 0, 1, True, False)

        return count(r) - count(l - 1)

