        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        edges.append((u, v))
        adj[u].append(v)

    # Shortest path length by number of edges.
    dist = [-1] * N
    dist[0] = 0
    q = deque([0])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)

    L = dist[N - 1]
    INF = 10**6

    def min_cost(D):
        if D == 0:
            return 0

        V = N * D + 2
        S = N * D
        T = S + 1
        dinic = Dinic(V)

        # Monotonicity of thresholds: phi(v) >= t+1 implies phi(v) >= t.
        for v in range(N):
            base = v * D
            for t in range(2, D + 1):
                dinic.add_edge(base + t - 1, base + t - 2, INF)

        # phi(1) = 0: all threshold nodes of vertex 1 are on sink side.
        for t in range(1, D + 1):
            dinic.add_edge(0 * D + t - 1, T, INF)

        # phi(N) = D: all threshold nodes of vertex N are on source side.
        for t in range(1, D + 1):
            dinic.add_edge(S, (N - 1) * D + t - 1, INF)

        # Edge constraints and costs.
        for u, v in edges:
            ubase = u * D
            vbase = v * D

            # Cost 1 iff phi(v) = phi(u) + 1.
            for t in range(1, D + 1):
                dinic.add_edge(vbase + t - 1, ubase + t - 1, 1)

            # Forbid phi(v) >= phi(u) + 2.
            for t in range(1, D):
                dinic.add_edge(vbase + t, ubase + t - 1, INF)

        return dinic.max_flow(S, T)

    for D in range(L, -1, -1):
        if min_cost(D) <= K:
            print(D)
            return


