import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:]

    fw = Fenwick(n)
    ans = 0

    for v in p:
        # number of values smaller than v that have appeared before v
        k = fw.sum(v - 1)
        m = (v - 1) - k
        ans += m * (v + k) // 2
        fw.add(v, 1)

    print(ans)

