class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, idx))

        cnt = [0] * (n + 1)
        owner = [0] * (n + 1)
        gain = [0] * m

        max1 = 0
        max2 = 0
        base = 0

        for r in range(1, n + 1):
            for l, idx in buckets[r]:
                if cnt[l] == 0:
                    owner[l] = idx
                cnt[l] += 1

                if l > max1:
                    max2 = max1
                    max1 = l
                elif l == max1:
                    pass
                elif l > max2:
                    max2 = l

            base += r - max1

            if max1 > 0 and cnt[max1] == 1:
                gain[owner[max1]] += max1 - max2

        if m == 0:
            return base
        return base + max(gain)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        ans = ['?'] * L
        forced = [False] * L

        # 1. Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]
                    forced[pos] = True

        # 2. Fill remaining positions with 'a'
        for i in range(L):
            if ans[i] == '?':
                ans[i] = 'a'

        # 3. Compute initial mismatch counts for all 'F' windows
        mismatch = [0] * n
        for i in range(n):
            if str1[i] == 'F':
                cnt = 0
                for j in range(m):
                    if ans[i + j] != str2[j]:
                        cnt += 1
                mismatch[i] = cnt

        # Precompute for each position which 'F' windows cover it
        covers = [[] for _ in range(L)]
        for i in range(n):
            if str1[i] == 'F':
                for j in range(m):
                    covers[i + j].append(i)

        # 4. Process 'F' constraints from left to right
        for i in range(n):
            if str1[i] == 'F' and mismatch[i] == 0:
                found = False
                # Try to change the rightmost possible position
                for j in range(i + m - 1, i - 1, -1):
                    if not forced[j]:
                        old_char = ans[j]
                        req_curr = str2[j - i]
                        mask = 1 << (ord(req_curr) - 97)

                        # Check previous 'F' windows that might rely solely on position j
                        for k in covers[j]:
                            if k >= i:
                                break
                            if mismatch[k] == 1 and old_char != str2[j - k]:
                                mask |= 1 << (ord(str2[j - k]) - 97)

                        # Find the smallest valid character
                        new_char = None
                        for c in range(26):
                            if not (mask >> c) & 1:
                                new_char = chr(97 + c)
                                break

                        if new_char is not None:
                            ans[j] = new_char
                            # Update mismatch counts for all 'F' windows containing j
                            for k in covers[j]:
                                if str1[k] == 'F':
                                    old_contrib = 1 if old_char != str2[j - k] else 0
                                    new_contrib = 1 if new_char != str2[j - k] else 0
                                    mismatch[k] += new_contrib - old_contrib
                            found = True
                            break
                if not found:
                    return ""

        return ''.join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_total = (n + 1) // 2
        even_total = n // 2

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        used = [False] * (n + 1)
        ans = []
        used_odd = 0
        used_even = 0

        for pos in range(n):
            for x in range(1, n + 1):
                if used[x]:
                    continue

                if ans and ((x & 1) == (ans[-1] & 1)):
                    continue

                uo = used_odd + (x & 1)
                ue = used_even + (1 - (x & 1))

                rem_odd = odd_total - uo
                rem_even = even_total - ue

                if rem_odd < 0 or rem_even < 0:
                    continue

                length = pos + 1

                if length == n:
                    cnt = 1 if rem_odd == 0 and rem_even == 0 else 0
                else:
                    next_odd = (x & 1) == 0
                    remaining_positions = n - length

                    if next_odd:
                        future_odd = (remaining_positions + 1) // 2
                    else:
                        future_odd = remaining_positions // 2

                    future_even = remaining_positions - future_odd

                    if rem_odd == future_odd and rem_even == future_even:
                        cnt = fact[rem_odd] * fact[rem_even]
                    else:
                        cnt = 0

                if cnt == 0:
                    continue

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)
                    used[x] = True
                    if x & 1:
                        used_odd += 1
                    else:
                        used_even += 1
                    break
            else:
                return []

        return ans

