def build_trans(T, maxd):
    trans = []
    for mask in range(16):
        cnt = {}
        for d in range(maxd):
            nm = 0
            for a in (0, 1):
                base = a * 2
                for c in (0, 1):
                    if mask & (1 << (base + c)):
                        for b in T[d][c]:
                            nm |= 1 << (base + b)
            cnt[nm] = cnt.get(nm, 0) + 1
        trans.append([(nm, c) for nm, c in cnt.items()])
    return trans

