import sys

def feasible(D, a, b, k, m):
    i = 0
    j = 0
    prev = -1
    ptr = 0
    R_prev = -1
    for g in range(m):
        t = b[g]
        low_val = t - D
        while i < k and a[i] < low_val:
            i += 1
        Lg = i
        if g == 0 and Lg > 0:
            return False
        if j < i:
            j = i
        high_val = t + D
        while j < k and a[j] <= high_val:
            j += 1
        Rg = j - 1

        if g > 0:
            low = prev + 1
            l_next = Lg - 1
            if l_next > low:
                low = l_next
            high = R_prev
            if high > k - 2:
                high = k - 2
            if low > high:
                return False
            if ptr < low:
                ptr = low
            d = b[g] - b[g-1]
            while ptr <= high and a[ptr+1] - a[ptr] < d:
                ptr += 1
            if ptr > high:
                return False
            prev = ptr
        R_prev = Rg

    if R_prev < k - 1:
        return False
    return True

