class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side
        n = len(points)
        arr = []
        for x, y in points:
            if x == 0:
                t = y
            elif y == side:
                t = side + x
            elif x == side:
                t = 3 * side - y
            else:
                t = 4 * side - x
            arr.append((t, x, y))
        arr.sort()
        t = [a[0] for a in arr]
        xs = [a[1] for a in arr]
        ys = [a[2] for a in arr]

        def compute_start_end(D):
            ext_t = t + [v + L for v in t]
            end = [0] * n
            R = 0
            for i in range(n):
                if R < i:
                    R = i
                while R < i + n and abs(xs[i] - xs[R % n]) + abs(ys[i] - ys[R % n]) < D:
                    R += 1
                end[i] = ext_t[R - 1]

            start = [0] * n
            Lidx = 0
            for i in range(n):
                cur = i + n
                if i == 0:
                    Lidx = cur
                    while Lidx > 0 and abs(xs[i] - xs[(Lidx - 1) % n]) + abs(ys[i] - ys[(Lidx - 1) % n]) < D:
                        Lidx -= 1
                else:
                    while Lidx < cur and abs(xs[i] - xs[Lidx % n]) + abs(ys[i] - ys[Lidx % n]) >= D:
                        Lidx += 1
                st = ext_t[Lidx]
                if st > t[i]:
                    st -= L
                start[i] = st
            return start, end

        def feasible(D):
            if D == 0:
                return True
            start, end = compute_start_end(D)
            ext_t = t + [v + L for v in t]
            end_ext = [0] * (2 * n)
            for i in range(2 * n):
                end_ext[i] = end[i % n] + (i // n) * L

            dp = ext_t[:]
            INF = 10**18
            for _ in range(2, k + 1):
                suff = [0] * (2 * n + 1)
                suff[2 * n] = INF
                for i in range(2 * n - 1, -1, -1):
                    suff[i] = dp[i] if dp[i] < suff[i + 1] else suff[i + 1]

                new_dp = [INF] * (2 * n)
                idx = 0
                for i in range(2 * n):
                    while idx < 2 * n and ext_t[idx] <= end_ext[i]:
                        idx += 1
                    if idx < 2 * n:
                        new_dp[i] = suff[idx]
                dp = new_dp

            for i in range(n):
                if dp[i] < start[i] + L:
                    return True
            return False

        low, high = 0, 2 * side
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low

