def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N = data[0]
    adj = [[] for _ in range(N)]
    idx = 1
    for _ in range(N - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    if N < 5:
        print(-1)
        return

    parent = [-1] * N
    order = []
    stack = [0]
    parent[0] = -2

    while stack:
        v = stack.pop()
        order.append(v)
        for u in adj[v]:
            if u == parent[v]:
                continue
            parent[u] = v
            stack.append(u)

    # down[v] = F(v, parent[v]) for v != root
    down = [1] * N
    for v in reversed(order):
        vals = []
        for u in adj[v]:
            if parent[u] == v:
                vals.append(down[u])
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[v] = 1 + vals[0] + vals[1] + vals[2]
        else:
            down[v] = 1

    # up[v] = F(parent[v], v) for v != root
    up = [0] * N
    ans = -1

    for v in order:
        arr = []
        for u in adj[v]:
            if parent[u] == v:
                arr.append((down[u], u))
            elif u == parent[v]:
                arr.append((up[v], u))

        arr.sort(key=lambda x: x[0], reverse=True)
        deg = len(arr)

        # v as root of the alkane, degree 4
        if deg >= 4:
            cand = 1 + arr[0][0] + arr[1][0] + arr[2][0] + arr[3][0]
            if cand > ans:
                ans = cand

        # v as root of the alkane, degree 1
        if deg >= 1 and arr[0][0] > 1:
            cand = 1 + arr[0][0]
            if cand > ans:
                ans = cand

        # compute up values for children
        for u in adj[v]:
            if parent[u] == v:
                sm = 0
                cnt = 0
                for val, node in arr:
                    if node == u:
                        continue
                    sm += val
                    cnt += 1
                    if cnt == 3:
                        break
                if cnt == 3:
                    up[u] = 1 + sm
                else:
                    up[u] = 1

    print(ans)


