class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        N = n * m
        vals = [0] * N
        for i in range(n):
            base = i * m
            row = grid[i]
            for j in range(m):
                vals[base + j] = row[j]

        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        cw = [1, 2, 3, 0]

        # f1[d][idx] = longest straight alternating segment starting at idx in direction d
        f1 = []
        for d in range(4):
            arr = [1] * N
            di, dj = dirs[d]
            if di > 0:
                i_range = range(n - 1, -1, -1)
            else:
                i_range = range(n)
            if dj > 0:
                j_range = range(m - 1, -1, -1)
            else:
                j_range = range(m)
            for i in i_range:
                base = i * m
                ni = i + di
                for j in j_range:
                    idx = base + j
                    v = vals[idx]
                    e = 0 if v == 2 else 2
                    nj = j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        if vals[nidx] == e:
                            arr[idx] = 1 + arr[nidx]
            f1.append(arr)

        starts = [idx for idx, v in enumerate(vals) if v == 1]
        if not starts:
            return 0

        ans = 0
        for d in range(4):
            arr0 = [1] * N
            di, dj = dirs[d]
            d2 = cw[d]
            di2, dj2 = dirs[d2]
            f1_turn = f1[d2]
            if di > 0:
                i_range = range(n - 1, -1, -1)
            else:
                i_range = range(n)
            if dj > 0:
                j_range = range(m - 1, -1, -1)
            else:
                j_range = range(m)
            for i in i_range:
                base = i * m
                ni = i + di
                ni2 = i + di2
                for j in j_range:
                    idx = base + j
                    v = vals[idx]
                    e = 0 if v == 2 else 2
                    best = 1
                    nj = j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        if vals[nidx] == e:
                            val = 1 + arr0[nidx]
                            if val > best:
                                best = val
                    nj2 = j + dj2
                    if 0 <= ni2 < n and 0 <= nj2 < m:
                        nidx2 = ni2 * m + nj2
                        if vals[nidx2] == e:
                            val = 1 + f1_turn[nidx2]
                            if val > best:
                                best = val
                    arr0[idx] = best
            for idx in starts:
                if arr0[idx] > ans:
                    ans = arr0[idx]

        return ans

from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)

        def kmp_occ(text: str, pat: str):
            if not pat:
                return []
            m = len(pat)
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                lps[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = lps[j - 1]
            return res

        occA = kmp_occ(s, A) if A else None
        occB = kmp_occ(s, B) if B else None
        occC = kmp_occ(s, C) if C else None

        if A and not occA:
            return -1
        if B and not occB:
            return -1
        if C and not occC:
            return -1

        lenA, lenB, lenC = len(A), len(B), len(C)
        ans = 10**18

        iterB = occB if B else range(n + 1)

        for i in iterB:
            if A:
                idx = bisect_right(occA, i - lenA) - 1
                if idx < 0:
                    continue
                left = occA[idx]
            else:
                left = i

            if C:
                idx = bisect_left(occC, i + lenB)
                if idx >= len(occC):
                    continue
                right = occC[idx]
            else:
                right = i + lenB

            length = right + lenC - left
            if length < ans:
                ans = length

        return ans if ans != 10**18 else -1

