    N = int(data[0])
    A = list(map(int, data[1:]))
    m = N - 1

    prime_exps = {}

    for i, val in enumerate(A):
        x = val
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                if d not in prime_exps:
                    prime_exps[d] = [0] * m
                prime_exps[d][i] = cnt
            d += 1
        if x > 1:
            if x not in prime_exps:
                prime_exps[x] = [0] * m
            prime_exps[x][i] = 1

    ans = 1

    for p, a in prime_exps.items():
        S = sum(a)

        powp = [1] * (S + 1)
        for e in range(1, S + 1):
            powp[e] = (powp[e - 1] * p) % MOD

        dp0 = [0] * (S + 1)
        dp1 = [0] * (S + 1)

        dp1[0] = 1
        for e in range(1, S + 1):
            dp0[e] = powp[e]

        for d in a:
            ndp0 = [0] * (S + 1)
            ndp1 = [0] * (S + 1)

            if d == 0:
                ndp1[0] = dp1[0]
                for ne in range(1, S + 1):
                    w = powp[ne]
                    ndp0[ne] = (dp0[ne] * w) % MOD
                    ndp1[ne] = (dp1[ne] * w) % MOD
            else:
                if d <= S:
                    ndp1[0] = (dp0[d] + dp1[d]) % MOD

                for ne in range(1, S + 1):
                    val0 = 0
                    idx = ne - d
                    if idx >= 0:
                        val0 += dp0[idx]
                    idx = ne + d
                    if idx <= S:
                        val0 += dp0[idx]

                    val1 = 0
                    idx = ne - d
                    if idx >= 0:
                        val1 += dp1[idx]
                    idx = ne + d
                    if idx <= S:
                        val1 += dp1[idx]

                    if val0:
                        ndp0[ne] = (val0 * powp[ne]) % MOD
                    if val1:
                        ndp1[ne] = (val1 * powp[ne]) % MOD

            dp0, dp1 = ndp0, ndp1

        F = sum(dp1) % MOD
        ans = (ans * F) % MOD

    print(ans)


