class Solution:
    def countSubstrings(self, s: str) -> int:
        digits = [ord(ch) - 48 for ch in s]
        ans = 0

        for d in range(1, 10):
            dp = [0] * d
            for c in digits:
                ndp = [0] * d
                for r in range(d):
                    cnt = dp[r]
                    if cnt:
                        ndp[(r * 10 + c) % d] += cnt
                ndp[c % d] += 1
                dp = ndp

                if c == d:
                    ans += dp[0]

        return ans

from array import array

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""
        s = [ord(ch) - 97 for ch in caption]
        INF = 10**9

        counts = [0] * 26
        for x in s:
            counts[x] += 1

        P = [0] * 26
        for c in range(26):
            total = 0
            for x in range(26):
                if counts[x]:
                    total += counts[x] * abs(x - c)
            P[c] = total

        size = (n + 1) * 26
        h = array('i', [INF]) * size
        bestJ = array('i', [-1]) * size

        minV = [INF] * 26
        best = [-1] * 26

        for i in range(n, -1, -1):
            j = i + 3
            if j <= n:
                c1 = s[i]
                c2 = s[i+1]
                c3 = s[i+2]
                if j == n:
                    for c in range(26):
                        delta = abs(c1 - c) + abs(c2 - c) + abs(c3 - c)
                        V = P[c] + delta
                        if V < minV[c]:
                            minV[c] = V
                            best[c] = j
                else:
                    base = j * 26
                    min1_val = INF
                    min1_idx = -1
                    min2_val = INF
                    min2_idx = -1
                    for d in range(26):
                        val = h[base + d]
                        if val < min1_val:
                            min2_val = min1_val
                            min2_idx = min1_idx
                            min1_val = val
                            min1_idx = d
                        elif val < min2_val:
                            min2_val = val
                            min2_idx = d
                    for c in range(26):
                        if c != min1_idx:
                            g = min1_val
                            nextc = min1_idx if min1_idx != -1 else 26
                        else:
                            g = min2_val
                            nextc = min2_idx if min2_idx != -1 else 26
                        delta = abs(c1 - c) + abs(c2 - c) + abs(c3 - c)
                        V = P[c] + delta + g
                        if V < minV[c]:
                            minV[c] = V
                            best[c] = j
                        elif V == minV[c]:
                            if nextc < c:
                                best[c] = j

            base_i = i * 26
            for c in range(26):
                if minV[c] < INF:
                    h[base_i + c] = minV[c] - P[c]
                    bestJ[base_i + c] = best[c]
                else:
                    h[base_i + c] = INF
                    bestJ[base_i + c] = -1

            if i > 0:
                x = s[i-1]
                for c in range(26):
                    P[c] -= abs(x - c)

        min_cost = INF
        for c in range(26):
            val = h[c]
            if val < min_cost:
                min_cost = val
        if min_cost >= INF:
            return ""

        res = []
        i = 0
        prev = 26
        while i < n:
            best_val = INF
            for c in range(26):
                if c == prev:
                    continue
                val = h[i * 26 + c]
                if val < best_val:
                    best_val = val
            best_c = -1
            for c in range(26):
                if c == prev:
                    continue
                if h[i * 26 + c] == best_val:
                    best_c = c
                    break
            if best_c == -1:
                return ""
            j = bestJ[i * 26 + best_c]
            if j < i + 3:
                return ""
            res.append(chr(best_c + 97) * (j - i))
            i = j
            prev = best_c

        return ''.join(res)

import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2].strip()
    s_vals = [ord(ch) - 97 for ch in S]

    states = 1 << N
    trans = [[0] * 26 for _ in range(states)]

    for mask in range(states):
        row = [0] * (N + 1)
        for i in range(1, N + 1):
            row[i] = row[i - 1] + ((mask >> (i - 1)) & 1)

        for c in range(26):
            nxt = [0] * (N + 1)
            for i in range(1, N + 1):
                val = row[i]
                if nxt[i - 1] > val:
                    val = nxt[i - 1]
                if s_vals[i - 1] == c:
                    cand = row[i - 1] + 1
                    if cand > val:
                        val = cand
                nxt[i] = val

            newmask = 0
            for i in range(1, N + 1):
                if nxt[i] != nxt[i - 1]:
                    newmask |= 1 << (i - 1)
            trans[mask][c] = newmask

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, cnt in enumerate(dp):
            if cnt:
                tr = trans[mask]
                for ns in tr:
                    v = ndp[ns] + cnt
                    if v >= MOD:
                        v -= MOD
                    ndp[ns] = v
        dp = ndp

    pop = [0] * states
    for mask in range(1, states):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    ans = [0] * (N + 1)
    for mask, cnt in enumerate(dp):
        if cnt:
            k = pop[mask]
            ans[k] = (ans[k] + cnt) % MOD

    sys.stdout.write(" ".join(map(str, ans)))

