    main()

import sys
from bisect import bisect_left

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    groups = [[] for _ in range(3)]

    idx = 2
    for _ in range(N):
        v = data[idx]
        a = data[idx + 1]
        c = data[idx + 2]
        idx += 3
        groups[v - 1].append((c, a))

    dps = []
    for group in groups:
        dp = [-1] * (X + 1)
        dp[0] = 0

        for c, a in group:
            d = dp
            for s in range(X, c - 1, -1):
                prev = d[s - c]
                if prev >= 0:
                    val = prev + a
                    if val > d[s]:
                        d[s] = val

        best = 0
        for s in range(1, X + 1):
            if dp[s] < best:
                dp[s] = best
            else:
                best = dp[s]

        dps.append(dp)

    high = min(dp[X] for dp in dps)
    low = 0

    while low < high:
        mid = (low + high + 1) // 2
        total_cost = 0
        ok = True

        for dp in dps:
            pos = bisect_left(dp, mid)
            if pos > X:
                ok = False
                break
            total_cost += pos
            if total_cost > X:
                ok = False
                break

        if ok:
            low = mid
        else:
            high = mid - 1

    print(low)

