    main()

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def min_contrib(arr: List[int]) -> int:
            n = len(arr)

            prev_le = [-1] * n
            stack = []
            for i, x in enumerate(arr):
                while stack and arr[stack[-1]] > x:
                    stack.pop()
                prev_le[i] = stack[-1] if stack else -1
                stack.append(i)

            next_lt = [n] * n
            stack = []
            for i in range(n - 1, -1, -1):
                x = arr[i]
                while stack and arr[stack[-1]] >= x:
                    stack.pop()
                next_lt[i] = stack[-1] if stack else n
                stack.append(i)

            def tri(t: int) -> int:
                if t < 0:
                    return 0
                return (t + 1) * (t + 2) // 2

            S = k - 1
            total = 0

            for i, x in enumerate(arr):
                A = i - prev_le[i]
                B = next_lt[i] - i
                cnt = tri(S) - tri(S - A) - tri(S - B) + tri(S - A - B)
                total += x * cnt

            return total

        return min_contrib(nums) - min_contrib([-x for x in nums])

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    MOD = int(data[1])
    half = N // 2
    Mmax = N * (N - 1) // 2
    max_n = max(N, Mmax)

    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_n + 1)
    invfact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    # T[a][b] = list of (shift, coefficient) for transition from previous layer size a to new layer size b
    T = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            internal = b * (b - 1) // 2
            shifts = []
            for j in range(b + 1):
                coeff = comb(b, j)
                if (b - j) & 1:
                    coeff = (MOD - coeff) % MOD
                shift = a * j + internal
                shifts.append((shift, coeff))
            T[a][b] = shifts

    # dp[u][(even_count, last_size, next_parity)] = polynomial in y = 1+x
    dp = [dict() for _ in range(N + 1)]
    dp[1][(1, 1, 1)] = [1]  # root: even count 1, last size 1, next layer odd

    final_y = None

    for u in range(1, N + 1):
        states = dp[u]
        if not states:
            continue

        # reduce modulo and trim trailing zeros
        for key in list(states.keys()):
            poly = states[key]
            for i in range(len(poly)):
                poly[i] %= MOD
            while poly and poly[-1] == 0:
                poly.pop()
            if not poly:
                del states[key]

        if u == N:
            final_y = [0] * (Mmax + 1)
            for (e, a, p), poly in states.items():
                if e == half:
                    for d, val in enumerate(poly):
                        final_y[d] = (final_y[d] + val) % MOD
            break

        R = N - u
        for (e, a, p), poly in states.items():
            if not poly:
                continue
            L = len(poly)
            pl = poly

            for b in range(1, R + 1):
                new_e = e + (b if p == 0 else 0)
                if new_e > half:
                    continue
                new_u = u + b
                if new_u - new_e > half:
                    continue

                new_p = 1 - p
                label = fact[N - u] * invfact[b] % MOD * invfact[N - u - b] % MOD

                key = (new_e, b, new_p)
                new_poly = dp[new_u].get(key)
                if new_poly is None:
                    new_poly = []
                    dp[new_u][key] = new_poly

                shifts = T[a][b]
                max_shift = shifts[-1][0]
                need = L + max_shift
                if len(new_poly) < need:
                    new_poly.extend([0] * (need - len(new_poly)))

                np = new_poly
                for shift, coeff in shifts:
                    c = coeff * label % MOD
                    for d in range(L):
                        np[d + shift] += pl[d] * c

        dp[u] = None

    if final_y is None:
        final_y = [0] * (Mmax + 1)

    # Convert F_y(y) to F_x(x) by y = 1 + x
    ans = [0] * (Mmax + 1)
    for m in range(Mmax + 1):
        total = 0
        for d in range(m, Mmax + 1):
            if final_y[d]:
                total = (total + final_y[d] * comb(d, m)) % MOD
        ans[m] = total

    start = N - 1
    out = ' '.join(str(ans[m]) for m in range(start, Mmax + 1))
    sys.stdout.write(out)

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(H)]
    Q, sh, sw = map(int, input().split())
    sh -= 1
    sw -= 1

    updates = []
    for _ in range(Q):
        line = input().split()
        d = line[0]
        a = int(line[1])
        if d == 'L':
            sw -= 1
        elif d == 'R':
            sw += 1
        elif d == 'U':
            sh -= 1
        elif d == 'D':
            sh += 1
        updates.append((sh, sw, a))

    B = 50
    out = []

    for block_start in range(0, Q, B):
        block = updates[block_start:block_start + B]

        # base DP
        dp = [[0] * W for _ in range(H)]
        for i in range(H):
            row = dp[i]
            Arow = A[i]
            if i == 0:
                row[0] = Arow[0] % MOD
                for j in range(1, W):
                    row[j] = Arow[j] * row[j - 1] % MOD
            else:
                prev = dp[i - 1]
                row[0] = Arow[0] * prev[0] % MOD
                for j in range(1, W):
                    row[j] = Arow[j] * (prev[j] + row[j - 1]) % MOD
        base_ans = dp[H - 1][W - 1]

        # suffix DP
        suf = [[0] * W for _ in range(H)]
        for i in range(H - 1, -1, -1):
            row = suf[i]
            Arow = A[i]
            if i == H - 1:
                row[W - 1] = Arow[W - 1] % MOD
                for j in range(W - 2, -1, -1):
                    row[j] = Arow[j] * row[j + 1] % MOD
            else:
                nextrow = suf[i + 1]
                row[W - 1] = Arow[W - 1] * nextrow[W - 1] % MOD
                for j in range(W - 2, -1, -1):
                    row[j] = Arow[j] * (nextrow[j] + row[j + 1]) % MOD

        cell_set = set()
        for h, w, a in block:
            cell_set.add((h, w))
        special = list(cell_set)
        special.sort()
        K = len(special)
        cell_to_idx = {cell: i for i, cell in enumerate(special)}

        P_excl = [0] * K
        S_excl = [0] * K
        for idx, (h, w) in enumerate(special):
            val = 0
            if h > 0:
                val = (val + dp[h - 1][w]) % MOD
            if w > 0:
                val = (val + dp[h][w - 1]) % MOD
            if h == 0 and w == 0:
                val = 1
            P_excl[idx] = val

            val = 0
            if h < H - 1:
                val = (val + suf[h + 1][w]) % MOD
            if w < W - 1:
                val = (val + suf[h][w + 1]) % MOD
            if h == H - 1 and w == W - 1:
                val = 1
            S_excl[idx] = val

        has_zero = False
        for h, w in special:
            if A[h][w] == 0:
                has_zero = True
                break

        if not has_zero:
            min_h = min(c[0] for c in special)
            max_h = max(c[0] for c in special)
            min_w = min(c[1] for c in special)
            max_w = max(c[1] for c in special)
            bh = max_h - min_h + 1
            bw = max_w - min_w + 1

            W_mat = [[0] * K for _ in range(K)]
            for i, (eh, ew) in enumerate(special):
                sh = eh - min_h
                sw = ew - min_w
                dp_sub = [[0] * bw for _ in range(bh)]
                dp_sub[sh][sw] = 1
                for r in range(sh, bh):
                    for c in range(sw, bw):
                        if r == sh and c == sw:
                            continue
                        val = 0
                        if r > sh:
                            val = (val + dp_sub[r - 1][c]) % MOD
                        if c > sw:
                            val = (val + dp_sub[r][c - 1]) % MOD
                        dp_sub[r][c] = val * A[min_h + r][min_w + c] % MOD
                for j, (dh, dw) in enumerate(special):
                    if dh >= eh and dw >= ew:
                        sr = dh - min_h
                        sc = dw - min_w
                        W_mat[i][j] = dp_sub[sr][sc]

            r = [1] * K
            cur_val = [A[h][w] for h, w in special]
            for h, w, a in block:
                idx = cell_to_idx[(h, w)]
                cur_val[idx] = a
                base_val = A[h][w]
                new_r = a * pow(base_val, MOD - 2, MOD) % MOD
                r[idx] = new_r

                F = [0] * K
                for i in range(K):
                    val = P_excl[i]
                    for j in range(i):
                        val = (val + F[j] * (r[j] - 1) * W_mat[j][i]) % MOD
                    F[i] = val % MOD

                ans = base_ans
                for i in range(K):
                    if r[i] != 1:
                        ans = (ans + F[i] * (r[i] - 1) * S_excl[i]) % MOD
                out.append(str(ans % MOD))

            for h, w, a in block:
                A[h][w] = a
        else:
            for h, w, a in block:
                A[h][w] = a
                dp = [[0] * W for _ in range(H)]
                for i in range(H):
                    row = dp[i]
                    Arow = A[i]
                    if i == 0:
                        row[0] = Arow[0] % MOD
                        for j in range(1, W):
                            row[j] = Arow[j] * row[j - 1] % MOD
                    else:
                        prev = dp[i - 1]
                        row[0] = Arow[0] * prev[0] % MOD
                        for j in range(1, W):
                            row[j] = Arow[j] * (prev[j] + row[j - 1]) % MOD
                out.append(str(dp[H - 1][W - 1]))

    print('\n'.join(out))

