import sys
from operator import mul

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))

    A = [[0] * N for _ in range(N)]
    K = 0
    for i in range(N):
        for j in range(N):
            v = int(next(it))
            A[i][j] = v
            if v == 0:
                K += 1

    # p = 2: zeros become 1, non-zeros are already 1, so B is all ones.
    if p == 2:
        ans = N & 1
        out = '\n'.join(' '.join(str(ans) for _ in range(N)) for _ in range(N))
        sys.stdout.write(out)
        return

    # F: fixed non-zero edges only
    F = [[A[i][j] if A[i][j] != 0 else 0 for j in range(N)] for i in range(N)]

    def mat_mul(X, Y):
        mod = p
        Yt = list(zip(*Y))
        return [[sum(map(mul, row, col)) % mod for col in Yt] for row in X]

    # Compute F^p modulo p
    res = [[0] * N for _ in range(N)]
    for i in range(N):
        res[i][i] = 1 % p

    base = F
    e = p
    while e > 0:
        if e & 1:
            res = mat_mul(res, base)
        e >>= 1
        if e:
            base = mat_mul(base, base)

    P = res

    # Contributions from zero entries
    Csum = [[0] * N for _ in range(N)]

    # For p = 3, a non-self zero (u, v) contributes F[v][u] at (u, v).
    if p == 3:
        for i in range(N):
            Ai = A[i]
            Ci = Csum[i]
            for j in range(N):
                if Ai[j] == 0 and i != j:
                    Ci[j] = (Ci[j] + F[j][i]) % p

    # Self-loop zeros (u, u) contribute to row u and column u.
    for u in range(N):
        if A[u][u] == 0:
            rowF = F[u]
            Crow = Csum[u]
            for j in range(N):
                if j != u:
                    Crow[j] = (Crow[j] + rowF[j]) % p
            for i in range(N):
                if i != u:
                    Csum[i][u] = (Csum[i][u] + F[i][u]) % p

    T = [[(P[i][j] + Csum[i][j]) % p for j in range(N)] for i in range(N)]

    # Multiply by (-1)^K
    if K & 1:
        for i in range(N):
            Ti = T[i]
            for j in range(N):
                if Ti[j]:
                    Ti[j] = p - Ti[j]

    out_lines = [' '.join(str(x % p) for x in row) for row in T]
    sys.stdout.write('\n'.join(out_lines))


