    solve()

import sys

def solve():
    input = sys.stdin.readline
    N, M, A, B = map(int, input().split())
    intervals = []
    for _ in range(M):
        L, R = map(int, input().split())
        intervals.append((L, R))

    # Case 1: fixed step size
    if A == B:
        if (N - 1) % A != 0:
            print("No")
            return
        for L, R in intervals:
            # smallest integer >= L congruent to 1 modulo A
            rem = (1 - L) % A
            cand = L + rem
            if cand <= R:
                print("No")
                return
        print("Yes")
        return

    # Case 2: A < B
    # Merge adjacent bad intervals into maximal contiguous bad blocks
    blocks = []
    for L, R in intervals:
        if not blocks:
            blocks.append([L, R])
        else:
            if L <= blocks[-1][1] + 1:
                if R > blocks[-1][1]:
                    blocks[-1][1] = R
            else:
                blocks.append([L, R])

    # If any contiguous bad block is too long, it cannot be jumped over
    for l, r in blocks:
        if r - l + 1 >= B:
            print("No")
            return

    C = B - A
    prefix = (1 << (C + 1)) - 1
    top = 1 << (B - 1)
    all_ones = (1 << B) - 1
    SKIP = 500  # safely larger than the worst-case stabilization time

    def advance_good(mask, cur, length):
        if length <= 0:
            return mask, cur
        steps = SKIP if length > SKIP else length
        for _ in range(steps):
            if mask & prefix:
                mask = (mask >> 1) | top
            else:
                mask >>= 1
        if length > SKIP and mask:
            mask = all_ones
        return mask, cur + length

    cur = 1
    mask = top  # R[1] = 1

    for l, r in blocks:
        # good gap before this bad block
        length = (l - 1) - cur
        mask, cur = advance_good(mask, cur, length)

        # bad block itself: every new square is unreachable
        num_bad = r - l + 1
        for _ in range(num_bad):
            mask >>= 1
        cur = r

    # final good gap up to N
    length = N - cur
    mask, cur = advance_good(mask, cur, length)

    if mask & top:
        print("Yes")
    else:
        print("No")


if __name__ == "__main__":
    solve()

