from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        # Sort intervals by right endpoint. Keep original index.
        arr = []
        for idx, (l, r, w) in enumerate(intervals):
            arr.append((r, l, w, idx))
        arr.sort()

        rights = [x[0] for x in arr]

        # dp[i][j] = best (weight, sorted tuple of indices)
        # using a subset of intervals among arr[0..i], choosing at most j intervals.
        dp = [[(0, ()) for _ in range(5)] for _ in range(n)]

        for i, (r, l, w, idx) in enumerate(arr):
            # Last interval that ends strictly before l.
            p = bisect_left(rights, l) - 1

            prev = dp[i - 1] if i > 0 else None

            for j in range(5):
                if prev is not None:
                    best_w, best_t = prev[j]
                else:
                    best_w, best_t = 0, ()

                if j >= 1:
                    if p >= 0:
                        old_w, old_t = dp[p][j - 1]
                    else:
                        old_w, old_t = 0, ()

                    cand_w = old_w + w
                    pos = bisect_left(old_t, idx)
                    cand_t = old_t[:pos] + (idx,) + old_t[pos:]

                    if cand_w > best_w or (cand_w == best_w and cand_t < best_t):
                        best_w, best_t = cand_w, cand_t

                dp[i][j] = (best_w, best_t)

        return list(dp[n - 1][4][1])

from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG = -10**18
        EMPTY = (0, NEG, NEG, NEG)

        def merge(a, b):
            if a[1] == NEG:
                return b
            if b[1] == NEG:
                return a
            s1, p1, su1, b1 = a
            s2, p2, su2, b2 = b
            s = s1 + s2
            p = p1 if p1 > s1 + p2 else s1 + p2
            su = su2 if su2 > s2 + su1 else s2 + su1
            best = b1 if b1 > b2 else b2
            cross = su1 + p2
            if cross > best:
                best = cross
            return (s, p, su, best)

        size = 1
        while size < n:
            size <<= 1

        tree = [EMPTY] * (2 * size)
        for i, v in enumerate(nums):
            tree[size + i] = (v, v, v, v)

        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[i << 1], tree[i << 1 | 1])

        def query(l, r):
            l += size
            r += size
            left = EMPTY
            right = EMPTY
            while l < r:
                if l & 1:
                    left = merge(left, tree[l])
                    l += 1
                if r & 1:
                    r -= 1
                    right = merge(tree[r], right)
                l >>= 1
                r >>= 1
            return merge(left, right)

        ans = query(0, n)[3]

        pos = defaultdict(list)
        for i, v in enumerate(nums):
            pos[v].append(i)

        for arr in pos.values():
            if len(arr) == n:
                continue

            combined = None
            start = 0

            for p in arr:
                if start < p:
                    gap = query(start, p)
                    if combined is None:
                        combined = gap
                    else:
                        combined = merge(combined, gap)
                start = p + 1

            if start < n:
                gap = query(start, n)
                if combined is None:
                    combined = gap
                else:
                    combined = merge(combined, gap)

            if combined is not None:
                val = combined[3]
                if val > ans:
                    ans = val

        return ans

