from collections import deque

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]

    indeg = [0] * N
    for v in A:
        indeg[v] += 1

    q = deque(i for i in range(N) if indeg[i] == 0)
    H = [None] * N

    while q:
        v = q.popleft()
        p = A[v]

        arrp = H[p]
        if arrp is None:
            arrp = [1] * (M + 1)
            H[p] = arrp

        arrv = H[v]
        if arrv is None:
            for t in range(1, M + 1):
                arrp[t] = (arrp[t] * t) % MOD
        else:
            s = 0
            for t in range(1, M + 1):
                s += arrv[t]
                if s >= MOD:
                    s -= MOD
                arrp[t] = (arrp[t] * s) % MOD
            H[v] = None

        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    visited = [False] * N
    ans = 1

    for i in range(N):
        if indeg[i] > 0 and not visited[i]:
            cycle = []
            v = i
            while not visited[v]:
                visited[v] = True
                cycle.append(v)
                v = A[v]

            prod = [1] * (M + 1)
            for v in cycle:
                arr = H[v]
                if arr is not None:
                    for t in range(1, M + 1):
                        prod[t] = (prod[t] * arr[t]) % MOD

            comp_sum = (sum(prod) - 1) % MOD
            ans = (ans * comp_sum) % MOD

    print(ans)


if __name__ == "__main__":
    solve()

