class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        INF = 10**9

        def can(limit: int) -> bool:
            dp0 = [INF] * (limit + 1)
            dp1 = [INF] * (limit + 1)

            dp0[1] = 0 if s[0] == '0' else 1
            dp1[1] = 0 if s[0] == '1' else 1

            for ch in s[1:]:
                ndp0 = [INF] * (limit + 1)
                ndp1 = [INF] * (limit + 1)

                cost0 = 1 if ch == '1' else 0
                cost1 = 1 if ch == '0' else 0

                best1 = min(dp1)
                if best1 < INF:
                    ndp0[1] = best1 + cost0

                for r in range(2, limit + 1):
                    if dp0[r - 1] < INF:
                        ndp0[r] = dp0[r - 1] + cost0

                best0 = min(dp0)
                if best0 < INF:
                    ndp1[1] = best0 + cost1

                for r in range(2, limit + 1):
                    if dp1[r - 1] < INF:
                        ndp1[r] = dp1[r - 1] + cost1

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

