    if not data:
        return
    n = data[0]
    A = data[1:1 + n]

    ans = 0
    for a in A:
        ans += a // (a & -a)

    max_sum = 2 * max(A)
    max_k = max_sum.bit_length() - 1

    for k in range(max_k + 1):
        m = 1 << (k + 1)
        mask = m - 1
        target = 1 << k

        groups = {}
        for a in A:
            r = a & mask
            g = groups.get(r)
            if g is None:
                groups[r] = (1, a)
            else:
                groups[r] = (g[0] + 1, g[1] + a)

        add = 0
        for r, (c, s) in groups.items():
            q = (target - r) & mask
            if r < q:
                gq = groups.get(q)
                if gq is not None:
                    c2, s2 = gq
                    add += s * c2 + s2 * c
            elif r == q and c > 1:
                add += s * (c - 1)

        if add:
            ans += add >> k

    print(ans)

