import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    A = [0] + [int(x) for x in data[1:1+N]]

    parent = [0] * (N + 1)
    left = [0] * (N + 1)
    right = [0] * (N + 1)
    stack = []

    # Build max Cartesian tree (ties: leftmost becomes ancestor)
    for i in range(1, N + 1):
        last = 0
        ai = A[i]
        while stack and A[stack[-1]] < ai:
            last = stack.pop()
        if stack:
            right[stack[-1]] = i
            parent[i] = stack[-1]
        if last:
            left[i] = last
            parent[last] = i
        stack.append(i)
    root = stack[0]

    L = [0] * (N + 1)
    R = [0] * (N + 1)
    S = [0] * (N + 1)

    # Iterative postorder traversal
    dfs_stack = [root]
    while dfs_stack:
        v = dfs_stack.pop()
        if v > 0:
            dfs_stack.append(-v)
            if right[v]:
                dfs_stack.append(right[v])
            if left[v]:
                dfs_stack.append(left[v])
        else:
            v = -v
            lv = L[left[v]] if left[v] else v
            rv = R[right[v]] if right[v] else v
            L[v] = lv
            R[v] = rv
            s = A[v]
            if left[v]:
                s += S[left[v]]
            if right[v]:
                s += S[right[v]]
            S[v] = s

    top = [0] * (N + 1)
    top[root] = root
    pre_stack = [root]
    while pre_stack:
        v = pre_stack.pop()
        if left[v]:
            child = left[v]
            if S[child] > A[v]:
                top[child] = top[v]
            else:
                top[child] = child
            pre_stack.append(child)
        if right[v]:
            child = right[v]
            if S[child] > A[v]:
                top[child] = top[v]
            else:
                top[child] = child
            pre_stack.append(child)

    ans = []
    for K in range(1, N + 1):
        if (L[K] < K and A[K - 1] < A[K]) or (K < R[K] and A[K + 1] < A[K]):
            fK = S[K]
        else:
            fK = A[K]
        p = parent[K]
        if p != 0 and fK > A[p]:
            ans.append(str(S[top[p]]))
        else:
            ans.append(str(fK))

    sys.stdout.write(' '.join(ans))

