    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        vals = {x for x in nums if x <= T}
        isolated = sum(1 for x in nums if x > T)

        if not vals:
            return isolated

        parent = list(range(T + 1))
        size = [1] * (T + 1)

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        for x in vals:
            for m in range(x, T + 1, x):
                union(x, m)

        roots = set()
        for x in vals:
            roots.add(find(x))

        return isolated + len(roots)
